     1→/**
     2→ * GEDCOM 5.5.1 Parser
     3→ * Handles parsing of GEDCOM format files into structured TypeScript objects
     4→ */
     5→
     6→import type {
     7→  GedcomFile,
     8→  GedcomLine,
     9→  GedcomRecord,
    10→  ParsedDate,
    11→  ParsedIndividual,
    12→  ParsedFamily,
    13→  ValidationError,
    14→} from "./types";
    15→
    16→export class GedcomParser {
    17→  private lines: GedcomLine[] = [];
    18→  private records: GedcomRecord[] = [];
    19→  private errors: ValidationError[] = [];
    20→
    21→  /**
    22→   * Parse GEDCOM 5.5.1 text into structured format
    23→   */
    24→  parse(content: string): GedcomFile {
    25→    this.lines = [];
    26→    this.records = [];
    27→    this.errors = [];
    28→
    29→    // Split into lines and filter empty lines
    30→    const rawLines = content.split(/\r?\n/).filter((line) => line.trim());
    31→
    32→    // Parse each line and handle continuations
    33→    this.parseLines(rawLines);
    34→
    35→    // Build hierarchical record structure
    36→    this.buildRecords();
    37→
    38→    // Extract specific records
    39→    const header = this.records.find((r) => r.type === "HEAD");
    40→    const trailer = this.records.find((r) => r.type === "TRLR");
    41→    const individuals = this.records.filter((r) => r.type === "INDI");
    42→    const families = this.records.filter((r) => r.type === "FAM");
    43→
    44→    if (!header) {
    45→      throw new Error("Missing required HEAD record");
    46→    }
    47→    if (!trailer) {
    48→      throw new Error("Missing required TRLR record");
    49→    }
    50→
    51→    // Extract charset and version from header
    52→    const charsetLine = header.tags.get("CHAR")?.[0];
    53→    const versionLine = header.tags.get("VERS")?.[0];
    54→    const gedcomLine = header.tags.get("GEDC")?.[0];
    55→    const gedcVersionLine = header.tags
    56→      .get("GEDC")
    57→      ?.find((l) => l.tag === "VERS");
    58→
    59→    const charset = charsetLine?.value || "UTF-8";
    60→    const version = gedcVersionLine?.value || "5.5.1";
    61→
    62→    return {
    63→      header,
    64→      individuals,
    65→      families,
    66→      trailer,
    67→      version,
    68→      charset,
    69→    };
    70→  }
    71→
    72→  /**
    73→   * Parse lines and handle continuation lines (CONT/CONC)
    74→   */
    75→  private parseLines(rawLines: string[]): void {
    76→    let i = 0;
    77→    while (i < rawLines.length) {
    78→      const line = rawLines[i];
    79→      const parsedLine = this.parseLine(line);
    80→
    81→      if (!parsedLine) {
    82→        i++;
    83→        continue;
    84→      }
    85→
    86→      // Handle continuation lines
    87→      let continuedValue = parsedLine.value;
    88→      let nextIndex = i + 1;
    89→
    90→      while (nextIndex < rawLines.length) {
    91→        const nextLine = rawLines[nextIndex];
    92→        const nextParsed = this.parseLine(nextLine);
    93→
    94→        // Check if it's a continuation line (CONT or CONC)
    95→        if (!nextParsed) {
    96→          break;
    97→        }
    98→
    99→        // Check if next line is at higher level or lower level with continuation tags
   100→        const nextLevel = this.getLevel(nextLine);
   101→        const currentLevel = parsedLine.level;
   102→
   103→        if (
   104→          nextLevel > currentLevel &&
   105→          (nextParsed.tag === "CONT" || nextParsed.tag === "CONC")
   106→        ) {
   107→          // CONT adds line break, CONC concatenates
   108→          if (nextParsed.tag === "CONT") {
   109→            continuedValue += "\n" + nextParsed.value;
   110→          } else {
   111→            continuedValue += nextParsed.value;
   112→          }
   113→          nextIndex++;
   114→        } else {
   115→          break;
   116→        }
   117→      }
   118→
   119→      parsedLine.value = continuedValue;
   120→      this.lines.push(parsedLine);
   121→      i = nextIndex;
   122→    }
   123→  }
   124→
   125→  /**
   126→   * Parse a single GEDCOM line
   127→   * Format: <level> <tag> [<xref>] [<value>]
   128→   */
   129→  private parseLine(line: string): GedcomLine | null {
   130→    // Match GEDCOM line pattern
   131→    // Level is required, tag is required, xref/value are optional
   132→    const match = line.match(
   133→      /^(\d+)\s+(@[\w#]+@)?\s*(\w+)(?:\s+(@[\w#]+@|.*))?$/
   134→    );
   135→
   136→    if (!match) {
   137→      return null;
   138→    }
   139→
   140→    const [, levelStr, xref, tag, valueOrPointer] = match;
   141→    const level = parseInt(levelStr, 10);
   142→
   143→    // Determine if valueOrPointer is a pointer or value
   144→    let pointer: string | undefined;
   145→    let value: string;
   146→
   147→    if (valueOrPointer?.match(/^@[\w#]+@$/)) {
   148→      pointer = valueOrPointer;
   149→      value = "";
   150→    } else {
   151→      value = valueOrPointer || "";
   152→    }
   153→
   154→    return {
   155→      level,
   156→      tag,
   157→      xref,
   158→      value: value.trim(),
   159→      pointer,
   160→    };
   161→  }
   162→
   163→  /**
   164→   * Get level from a line string
   165→   */
   166→  private getLevel(line: string): number {
   167→    const match = line.match(/^(\d+)\s+/);
   168→    return match ? parseInt(match[1], 10) : 0;
   169→  }
   170→
   171→  /**
   172→   * Build hierarchical record structure from lines
   173→   */
   174→  private buildRecords(): void {
   175→    const recordStack: GedcomRecord[] = [];
   176→    let currentRecord: GedcomRecord | null = null;
   177→    let currentParent: GedcomRecord | null = null;
   178→
   179→    for (const line of this.lines) {
   180→      // Top-level record
   181→      if (line.level === 0) {
   182→        // Save previous record
   183→        if (currentRecord) {
   184→          this.records.push(currentRecord);
   185→        }
   186→
   187→        const type = this.getRecordType(line.tag, line.xref);
   188→        currentRecord = {
   189→          type,
   190→          id: line.xref?.replace(/@/g, ""),
   191→          lines: [line],
   192→          tags: new Map(),
   193→        };
   194→        recordStack.length = 0;
   195→        recordStack.push(currentRecord);
   196→
   197→        // Add to tag map
   198→        const existing = currentRecord.tags.get(line.tag) || [];
   199→        existing.push(line);
   200→        currentRecord.tags.set(line.tag, existing);
   201→      } else if (currentRecord) {
   202→        // Add to current record
   203→        currentRecord.lines.push(line);
   204→
   205→        // Add to tag map
   206→        const existing = currentRecord.tags.get(line.tag) || [];
   207→        existing.push(line);
   208→        currentRecord.tags.set(line.tag, existing);
   209→      }
   210→    }
   211→
   212→    // Save last record
   213→    if (currentRecord) {
   214→      this.records.push(currentRecord);
   215→    }
   216→  }
   217→
   218→  /**
   219→   * Determine record type from tag
   220→   */
   221→  private getRecordType(
   222→    tag: string,
   223→    xref?: string
   224→  ): "INDI" | "FAM" | "HEAD" | "TRLR" | "OTHER" {
   225→    if (tag === "HEAD") return "HEAD";
   226→    if (tag === "TRLR") return "TRLR";
   227→    if (tag === "INDI") return "INDI";
   228→    if (tag === "FAM") return "FAM";
   229→    return "OTHER";
   230→  }
   231→
   232→  /**
   233→   * Parse GEDCOM date format
   234→   * Handles: "15 JAN 1985", "JAN 1985", "1985", "ABT 1985", "BEF 1985", "AFT 1985", "BET 1975 AND 1985"
   235→   * Returns ISO date (YYYY-MM-DD) or null if invalid/partial
   236→   */
   237→  parseDate(gedcomDate: string): string | null {
   238→    if (!gedcomDate || !gedcomDate.trim()) {
   239→      return null;
   240→    }
   241→
   242→    const trimmed = gedcomDate.trim();
   243→    const parsed = this.parseDateComponents(trimmed);
   244→
   245→    if (!parsed.year) {
   246→      return null;
   247→    }
   248→
   249→    // Validate day is reasonable
   250→    if (parsed.day && (parsed.day < 1 || parsed.day > 31)) {
   251→      return null;
   252→    }
   253→
   254→    // Build ISO date with available components
   255→    let isoDate = String(parsed.year).padStart(4, "0");
   256→
   257→    if (parsed.month) {
   258→      isoDate += "-" + String(parsed.month).padStart(2, "0");
   259→
   260→      if (parsed.day) {
   261→        isoDate += "-" + String(parsed.day).padStart(2, "0");
   262→      }
   263→    }
   264→
   265→    return isoDate;
   266→  }
   267→
   268→  /**
   269→   * Parse date components from GEDCOM date string
   270→   */
   271→  private parseDateComponents(dateStr: string): ParsedDate {
   272→    const result: ParsedDate = {
   273→      isApproximate: false,
   274→      raw: dateStr,
   275→    };
   276→
   277→    // Check for date qualifiers
   278→    let workingStr = dateStr.trim();
   279→    const qualifierMatch = workingStr.match(/^(ABT|BEF|AFT|BET)\s+/);
   280→    if (qualifierMatch) {
   281→      result.qualifier = qualifierMatch[1] as any;
   282→      result.isApproximate = true;
   283→      workingStr = workingStr.substring(qualifierMatch[0].length).trim();
   284→    }
   285→
   286→    // Handle "BET ... AND ..." format (e.g., "BET 1975 AND 1985" or "BET 1 JAN 1975 AND 1 JAN 1985")
   287→    if (result.qualifier === "BET") {
   288→      // Try full date format first: "BET 15 JAN 1975 AND 15 JAN 1985"
   289→      const betFullMatch = workingStr.match(
   290→        /^(\d{1,2})\s+(\w+)\s+(\d{4})\s+AND\s+(\d{1,2})\s+(\w+)\s+(\d{4})$/
   291→      );
   292→      if (betFullMatch) {
   293→        result.day = parseInt(betFullMatch[1], 10);
   294→        result.month = this.monthToNumber(betFullMatch[2]);
   295→        result.year = parseInt(betFullMatch[3], 10);
   296→        return result;
   297→      }
   298→
   299→      // Try year-only format: "BET 1975 AND 1985"
   300→      const betYearMatch = workingStr.match(/^(\d{4})\s+AND\s+(\d{4})$/);
   301→      if (betYearMatch) {
   302→        result.year = parseInt(betYearMatch[1], 10);
   303→        return result;
   304→      }
   305→    }
   306→
   307→    // Try full date format: "15 JAN 1985"
   308→    const fullMatch = workingStr.match(/^(\d{1,2})\s+(\w+)\s+(\d{4})$/);
   309→    if (fullMatch) {
   310→      result.day = parseInt(fullMatch[1], 10);
   311→      result.month = this.monthToNumber(fullMatch[2]);
   312→      result.year = parseInt(fullMatch[3], 10);
   313→      return result;
   314→    }
   315→
   316→    // Try month-year format: "JAN 1985"
   317→    const monthYearMatch = workingStr.match(/^(\w+)\s+(\d{4})$/);
   318→    if (monthYearMatch) {
   319→      result.month = this.monthToNumber(monthYearMatch[1]);
   320→      result.year = parseInt(monthYearMatch[2], 10);
   321→      return result;
   322→    }
   323→
   324→    // Try year only: "1985"
   325→    const yearMatch = workingStr.match(/^(\d{4})$/);
   326→    if (yearMatch) {
   327→      result.year = parseInt(yearMatch[1], 10);
   328→      return result;
   329→    }
   330→
   331→    return result;
   332→  }
   333→
   334→  /**
   335→   * Convert month name to number (1-12)
   336→   */
   337→  private monthToNumber(monthName: string): number | undefined {
   338→    const months: Record<string, number> = {
   339→      JAN: 1,
   340→      FEB: 2,
   341→      MAR: 3,
   342→      APR: 4,
   343→      MAY: 5,
   344→      JUN: 6,
   345→      JUL: 7,
   346→      AUG: 8,
   347→      SEP: 9,
   348→      SEPT: 9,
   349→      OCT: 10,
   350→      NOV: 11,
   351→      DEC: 12,
   352→    };
   353→    return months[monthName.toUpperCase()];
   354→  }
   355→
   356→  /**
   357→   * Parse name in GEDCOM format
   358→   * Format: "Given /Surname/" or "Given" or "/Surname/"
   359→   */
   360→  parseName(gedcomName: string): { firstName?: string; lastName?: string } {
   361→    if (!gedcomName || !gedcomName.trim()) {
   362→      return {};
   363→    }
   364→
   365→    const trimmed = gedcomName.trim();
   366→
   367→    // Find surname between forward slashes
   368→    const surnameMatch = trimmed.match(/\/([^\/]*)\//);
   369→    const lastName = surnameMatch ? surnameMatch[1].trim() : undefined;
   370→
   371→    // Extract given names (everything before and after surname)
   372→    let firstName: string | undefined;
   373→    if (surnameMatch) {
   374→      // Remove the /surname/ part and trim
   375→      const withoutSurname = trimmed.replace(/\/[^\/]*\//, "").trim();
   376→      firstName = withoutSurname || undefined;
   377→    } else {
   378→      // No surname markers, entire thing is given name
   379→      firstName = trimmed || undefined;
   380→    }
   381→
   382→    return {
   383→      firstName: firstName || undefined,
   384→      lastName: lastName || undefined,
   385→    };
   386→  }
   387→
   388→  /**
   389→   * Validate GEDCOM file structure
   390→   */
   391→  validate(file: GedcomFile): ValidationError[] {
   392→    const errors: ValidationError[] = [];
   393→
   394→    // Check for required records
   395→    if (!file.header) {
   396→      errors.push({
   397→        message: "Missing required HEAD record",
   398→        severity: "error",
   399→      });
   400→    }
   401→
   402→    if (!file.trailer) {
   403→      errors.push({
   404→        message: "Missing required TRLR record",
   405→        severity: "error",
   406→      });
   407→    }
   408→
   409→    // Check for unique xrefs
   410→    const xrefSet = new Set<string>();
   411→    const allRecords = [
   412→      file.header,
   413→      ...file.individuals,
   414→      ...file.families,
   415→      file.trailer,
   416→    ].filter((r): r is GedcomRecord => r !== null && r !== undefined);
   417→
   418→    for (const record of allRecords) {
   419→      if (record.id) {
   420→        if (xrefSet.has(record.id)) {
   421→          errors.push({
   422→            message: `Duplicate xref: ${record.id}`,
   423→            severity: "error",
   424→          });
   425→        }
   426→        xrefSet.add(record.id);
   427→      }
   428→    }
   429→
   430→    // Check for broken references in families
   431→    const personIds = new Set(file.individuals.map((i) => i.id));
   432→    const familyIds = new Set(file.families.map((f) => f.id));
   433→
   434→    for (const family of file.families) {
   435→      const husbandLine = family.tags.get("HUSB")?.[0];
   436→      const wifeLine = family.tags.get("WIFE")?.[0];
   437→      const childLines = family.tags.get("CHIL") || [];
   438→
   439→      if (
   440→        husbandLine?.pointer &&
   441→        !personIds.has(husbandLine.pointer.replace(/@/g, ""))
   442→      ) {
   443→        errors.push({
   444→          message: `Broken reference in family ${family.id}: HUSB ${husbandLine.pointer} not found`,
   445→          severity: "warning",
   446→        });
   447→      }
   448→
   449→      if (
   450→        wifeLine?.pointer &&
   451→        !personIds.has(wifeLine.pointer.replace(/@/g, ""))
   452→      ) {
   453→        errors.push({
   454→          message: `Broken reference in family ${family.id}: WIFE ${wifeLine.pointer} not found`,
   455→          severity: "warning",
   456→        });
   457→      }
   458→
   459→      for (const childLine of childLines) {
   460→        if (
   461→          childLine.pointer &&
   462→          !personIds.has(childLine.pointer.replace(/@/g, ""))
   463→        ) {
   464→          errors.push({
   465→            message: `Broken reference in family ${family.id}: CHIL ${childLine.pointer} not found`,
   466→            severity: "warning",
   467→          });
   468→        }
   469→      }
   470→    }
   471→
   472→    // Check for broken family references in individuals
   473→    for (const person of file.individuals) {
   474→      const famcLines = person.tags.get("FAMC") || [];
   475→      const famsLines = person.tags.get("FAMS") || [];
   476→
   477→      for (const line of famcLines) {
   478→        if (line.pointer && !familyIds.has(line.pointer.replace(/@/g, ""))) {
   479→          errors.push({
   480→            message: `Broken reference in person ${person.id}: FAMC ${line.pointer} not found`,
   481→            severity: "warning",
   482→          });
   483→        }
   484→      }
   485→
   486→      for (const line of famsLines) {
   487→        if (line.pointer && !familyIds.has(line.pointer.replace(/@/g, ""))) {
   488→          errors.push({
   489→            message: `Broken reference in person ${person.id}: FAMS ${line.pointer} not found`,
   490→            severity: "warning",
   491→          });
   492→        }
   493→      }
   494→    }
   495→
   496→    return errors;
   497→  }
   498→
   499→  /**
   500→   * Parse individual record into structured data
   501→   */
   502→  parseIndividual(record: GedcomRecord): ParsedIndividual {
   503→    const id = record.id || "unknown";
   504→
   505→    // Extract names
   506→    const names: Array<{
   507→      full: string;
   508→      firstName?: string;
   509→      lastName?: string;
   510→    }> = [];
   511→    const nameLines = record.tags.get("NAME") || [];
   512→    for (const line of nameLines) {
   513→      const { firstName, lastName } = this.parseName(line.value);
   514→      names.push({
   515→        full: line.value,
   516→        firstName,
   517→        lastName,
   518→      });
   519→    }
   520→
   521→    // Extract sex
   522→    const sexLine = record.tags.get("SEX")?.[0];
   523→    const sex =
   524→      sexLine?.value === "M" || sexLine?.value === "F" || sexLine?.value === "X"
   525→        ? sexLine.value
   526→        : undefined;
   527→
   528→    // Extract birth information
   529→    const birtLine = record.tags.get("BIRT")?.[0];
   530→    const birthDate = birtLine
   531→      ? this.parseDateFromRecord(record, "BIRT")
   532→      : undefined;
   533→    const birthPlace = this.getPlaceFromEvent(record, "BIRT");
   534→
   535→    // Extract death information
   536→    const deathLine = record.tags.get("DEAT")?.[0];
   537→    const deathDate = deathLine
   538→      ? this.parseDateFromRecord(record, "DEAT")
   539→      : undefined;
   540→    const deathPlace = this.getPlaceFromEvent(record, "DEAT");
   541→
   542→    // Extract occupation
   543→    const occuLine = record.tags.get("OCCU")?.[0];
   544→    const occupation = occuLine?.value;
   545→
   546→    // Extract notes (skip empty notes)
   547→    const notes: string[] = [];
   548→    const noteLines = record.tags.get("NOTE") || [];
   549→    for (const line of noteLines) {
   550→      const noteValue = line.value.trim();
   551→      if (noteValue) {
   552→        notes.push(noteValue);
   553→      }
   554→    }
   555→
   556→    // Extract family references
   557→    const familiesAsChild: string[] = [];
   558→    const famcLines = record.tags.get("FAMC") || [];
   559→    for (const line of famcLines) {
   560→      if (line.pointer) {
   561→        familiesAsChild.push(line.pointer.replace(/@/g, ""));
   562→      }
   563→    }
   564→
   565→    const familiesAsSpouse: string[] = [];
   566→    const famsLines = record.tags.get("FAMS") || [];
   567→    for (const line of famsLines) {
   568→      if (line.pointer) {
   569→        familiesAsSpouse.push(line.pointer.replace(/@/g, ""));
   570→      }
   571→    }
   572→
   573→    return {
   574→      id,
   575→      names: names.length > 0 ? names : [{ full: "" }],
   576→      sex,
   577→      birthDate,
   578→      birthPlace,
   579→      deathDate,
   580→      deathPlace,
   581→      occupation,
   582→      notes,
   583→      familiesAsChild,
   584→      familiesAsSpouse,
   585→    };
   586→  }
   587→
   588→  /**
   589→   * Parse family record into structured data
   590→   */
   591→  parseFamily(record: GedcomRecord): ParsedFamily {
   592→    const id = record.id || "unknown";
   593→
   594→    // Extract spouse information
   595→    const husbandLine = record.tags.get("HUSB")?.[0];
   596→    const wifeLine = record.tags.get("WIFE")?.[0];
   597→    const husband = husbandLine?.pointer?.replace(/@/g, "");
   598→    const wife = wifeLine?.pointer?.replace(/@/g, "");
   599→
   600→    // Extract children
   601→    const children: string[] = [];
   602→    const childLines = record.tags.get("CHIL") || [];
   603→    for (const line of childLines) {
   604→      if (line.pointer) {
   605→        children.push(line.pointer.replace(/@/g, ""));
   606→      }
   607→    }
   608→
   609→    // Extract marriage information
   610→    const marriageDate = this.parseDateFromRecord(record, "MARR");
   611→    const marriagePlace = this.getPlaceFromEvent(record, "MARR") || undefined;
   612→
   613→    // Extract divorce information
   614→    const divorceDate = this.parseDateFromRecord(record, "DIV");
   615→
   616→    // Extract notes (skip empty notes)
   617→    const notes: string[] = [];
   618→    const noteLines = record.tags.get("NOTE") || [];
   619→    for (const line of noteLines) {
   620→      const noteValue = line.value.trim();
   621→      if (noteValue) {
   622→        notes.push(noteValue);
   623→      }
   624→    }
   625→
   626→    return {
   627→      id,
   628→      husband,
   629→      wife,
   630→      children,
   631→      marriageDate,
   632→      marriagePlace,
   633→      divorceDate,
   634→      notes,
   635→    };
   636→  }
   637→
   638→  /**
   639→   * Parse date from an event tag (BIRT, DEAT, MARR, etc.)
   640→   */
   641→  private parseDateFromRecord(
   642→    record: GedcomRecord,
   643→    eventTag: string
   644→  ): string | undefined {
   645→    const eventLines = record.tags.get(eventTag) || [];
   646→    for (const eventLine of eventLines) {
   647→      // Look for DATE substructure
   648→      const eventIndex = record.lines.indexOf(eventLine);
   649→
   650→      // Find DATE lines that are children of this event
